import { Link } from 'lucide-react';

// AUTO-GENERATED BY BUILDAI ROUTE COMPILER (PHASE 1 FOUNDATION). DO NOT MODIFY DIRECTLY.
function makeRoute<T extends (...args: any[]) => string>(path: string, fn?: T): T & string {
  const f = (fn || (((..._args: any[]) => path) as unknown as T)) as any;
  for (const key of Object.getOwnPropertyNames(String.prototype)) {
    if (key === 'constructor' || key === 'valueOf' || key === 'toString') continue;
    try {
      const val = (String.prototype as any)[key];
      if (typeof val === 'function') {
        f[key] = function (...args: any[]) {
          return (path as any)[key](...args);
        };
      }
    } catch {}
  }
  f.toString = () => path;
  f.valueOf = () => path;
  try {
    Object.defineProperty(f, 'length', { value: path.length, configurable: true });
  } catch {}
  f[Symbol.toPrimitive] = () => path;
  // A route is handed to <Navigate to>, navigate() and <Link to> as-is. React Router treats anything that is
  // not a primitive string as a Path object and reads to.search.includes("#"), but copying String.prototype
  // above also copied String.prototype.search (a function). Present the router's Path shape explicitly so
  // those fields are strings, not string methods.
  f.pathname = path;
  f.search = '';
  f.hash = '';
  return f as T & string;
}

